  "id": "ALIM-025",
  "categoria": "Fichas técnicas de alimentos",
  "alimento": "Acerola",
  "pergunta": "Acerola: identidade e nomes",
  "resposta": "• Nome comum: acerola; cereja-das-Antilhas ou cereja-de-Barbados em algumas fontes.\n• Nome científico usado em literatura: Malpighia emarginata DC.; bases brasileiras também podem usar Malpighia glabra L. ou Malpighia spp. Preservar o nome que cada fonte atribui e armazenar um campo de nome normalizado sem apagar essa diferença.\n• Família: Malpighiaceae.\n• Sinônimos de busca: acerola, cereja-das-Antilhas, cereja-de-Barbados, Barbados cherry, West Indian cherry, acerola verde, acerola madura, polpa de acerola.",
