   "https://www.embrapa.br/en/web/agencia-de-informacao-tecnologica/cultivos/coco/producao/sistema-de-cultivo/colheita",
   "https://www.embrapa.br/en/web/hortalicas/busca-de-solucoes-tecnologicas/-/produto-servico/15/sistema-de-producao-da-cultura-do-coqueiro",
