   "https://www.infoteca.cnptia.embrapa.br/infoteca/handle/doc/114141",
   "https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/1174039/1/CPAC-2025-Fruticultura-tropical.pdf",
   "https://www.tbca.net.br/base-dados/int_composicao_alimentos.php?n0REd3kv7e86D%2BViXWYUnQ%3D%3D=gSUJtSN%2FnIuOu21SFJ%2BfEg%3D%3D",
