  "resposta": "Registro: TBCA BRC0028C, polpa de melão in natura, Brasil, Cucumis melo, por 100 g. Valores visíveis na ficha: 24 kcal e 93,0 g de umidade. O registro completo apresenta os nutrientes, mas nesta ficha não se reproduzem os componentes não confirmados individualmente; a espécie/tipo comercial não é estratificada. TBCA, melão.\nÁgua, açúcares, aroma, firmeza e pigmentos variam com tipo botânico, cultivar, ambiente, irrigação e maturidade.",
