   "https://www.embrapa.br/en/web/agencia-de-informacao-tecnologica/cultivos/morango/producao/colheita",
   "https://www.embrapa.br/en/web/agencia-de-informacao-tecnologica/cultivos/morango/pos-producao/armazenamento-refrigerado",
