  "resposta": "Refrigerar em saco ou recipiente limpo que mantenha umidade sem criar água livre. Guardar sem lavar ou secar completamente após lavagem. Consumir em poucos dias para melhor qualidade. Branquear e congelar em floretes e talos próprios; a textura amolece após descongelamento. Pode ser consumido cru higienizado, cozido no vapor, fervido brevemente, assado ou salteado; cozimento prolongado pode reduzir vitaminas solúveis em água e compostos sensíveis ao calor.",
