  "pergunta": "Cebola: identidade, tipos e variedades",
  "resposta": "Cebola de bulbo é Allium cepa L., família Amaryllidaceae. O bulbo é formado por folhas modificadas e pode ter casca e polpa brancas, amarelas, roxas ou avermelhadas. Tipos de dias curtos, intermediários ou longos diferem em adaptação ao fotoperíodo; cultivares brasileiras são selecionadas para regiões e épocas específicas. Cebola verde/cebolinha é forma de colheita e produto diferente. Sinônimos: cebola, cebola seca, cebola amarela, branca, roxa, onion. Cor não é identificação de cultivar.",
