  "resposta": "Cenoura é Daucus carota L. subsp. sativus, família Apiaceae. A raiz de reserva é a parte mais consumida; folhas jovens também são comestíveis, mas têm identidade nutricional própria. Cultivares comerciais são frequentemente classificadas por formato e adaptação: Nantes, Brasília, Kuroda, Alvorada, BRS Planalto, entre outras. Cor pode ser laranja, roxa, amarela, branca ou vermelha, conforme cultivar; registros nutricionais de cenoura laranja não devem ser aplicados automaticamente às outras cores. Sinônimos: cenoura, carrot, zanahoria.",
