  "resposta": "Planta de estação amena, embora cultivares tropicais permitam produção em regiões quentes. O grupo Brasília, desenvolvido para condições tropicais, é exemplo de adaptação brasileira. Solo profundo, solto, sem pedras ou torrões, bem drenado e com matéria orgânica favorece raízes retas. Plantio direto, desbaste no espaçamento adequado, irrigação uniforme na germinação e crescimento, capina superficial e rotação são importantes. Déficit hídrico, excesso de nitrogênio, compactação, calor e irregularidade de água podem produzir raízes deformadas, rachadas ou fibrosas. Colher quando diâmetro e comprimento atingirem padrão da cultivar, com cor intensa e textura firme; ciclo é variável e a safra depende da região e cultivar.",
