  "resposta": "Remover folhas se a raiz será armazenada, evitar machucados e refrigeração rápida em ambiente úmido sem água livre. Guardar limpa e seca em embalagem que reduza murcha. Lavar e descascar apenas conforme necessidade. Crua, cozida, assada, em purê, suco ou conserva. Congelar após branqueamento ou cozimento; textura amolece. Suco e purê têm concentração de nutrientes e fibra diferente da raiz inteira.",
