  "pergunta": "Chuchu: identidade e tipos",
  "resposta": "Chuchu é Sechium edule (Jacq.) Sw., família Cucurbitaceae. O fruto é a parte culinária usual, geralmente verde-claro, verde-escuro ou branco-creme, liso ou com sulcos/espinhos suaves, conforme variedade. A semente é achatada e aderida à polpa; a planta é trepadeira e pode produzir frutos sem fecundação completa. Sinônimos: chuchu, caiota, chayote, mirliton. Não confundir fruto com folhas e brotos da planta, que possuem usos regionais separados.",
