  "categoria": "Fichas técnicas de alimentos",
  "alimento": "Chuchu",
  "pergunta": "Chuchu: cultivo, época e colheita",
  "resposta": "Planta de clima quente a ameno e sem geadas fortes; desenvolvimento, florescimento e produção respondem a temperatura e fotoperíodo. Requer suporte ou estrutura para trepadeira, solo profundo, fértil, drenado, com água regular. Propaga-se frequentemente pelo fruto inteiro germinado; tutoramento, condução, capina, cobertura do solo e irrigação são práticas usuais. Monitorar doenças de cucurbitáceas e evitar encharcamento. Produção pode estender-se por vários meses após início da colheita; calendário depende do clima local. Colher frutos imaturos, tenros, com casca brilhante e sem endurecimento; tamanho comercial varia por mercado e variedade. Corte cuidadoso previne danos na planta e no fruto.",
