  "pergunta": "Couve-flor: identidade e variedades",
  "resposta": "Couve-flor é Brassica oleracea var. botrytis L., família Brassicaceae. A parte consumida é a inflorescência imatura compacta, ou cabeça. Cultivares brancas são mais comuns; também há materiais verdes, roxos e alaranjados. Variedade adapta-se a faixas térmicas distintas; calor na diferenciação da cabeça pode provocar folhas internas, granulação ou cabeças soltas. Sinônimos: couve-flor, cauliflower, coliflor. Distinguir brócolis e romanesco.",
