  "resposta": "Geralmente prefere clima ameno, mas existem cultivares para diferentes regiões. Exige solo fértil, bem drenado, boa retenção de água e irrigação uniforme, sobretudo na formação da cabeça. Mudanças bruscas de umidade e calor podem comprometer qualidade. Produção usa mudas transplantadas, controle de plantas daninhas, rotação entre famílias, manejo integrado de pragas e adubação baseada em análise. Colher a cabeça firme, compacta, com botões fechados e cor característica, antes de granulação ou abertura floral. Em variedades que necessitam branqueamento, folhas podem ser dobradas sobre a cabeça; isso depende da cultivar e sistema.",
