  "alimento": "Pepino",
  "pergunta": "Pepino: identidade e tipos",
  "resposta": "Pepino é Cucumis sativus L., família Cucurbitaceae. Tipos incluem pepino para salada, japonês/hoshi, caipira, conserva (pickling), holandês e mini, com diferenças de casca, tamanho, sementes e textura. Há cultivares partenocárpicas que formam fruto sem polinização. Frutos de conserva são geralmente menores e colhidos em estágio mais jovem. Sinônimos: pepino, cucumber, pepino japonês, caipira, holandês, de conserva.",
