  "categoria": "Fichas técnicas de alimentos",
  "alimento": "Pepino",
  "pergunta": "Pepino: produção e colheita",
  "resposta": "Cultura de clima quente, sensível a geada e frio. Exige solo fértil, drenado, pleno sol e água uniforme; irrigação localizada e tutoramento são comuns em cultivos protegidos. Manejo inclui semeadura direta ou transplantio, rotação de cucurbitáceas, polinização para cultivares dependentes de abelhas, controle de plantas daninhas e monitoramento de oídio, míldio e pragas. Colher frutos imaturos, firmes e verdes no tamanho comercial do tipo; frutos amarelados ou muito grandes tendem a ter sementes endurecidas. Colheita frequente mantém qualidade e produção. É possível cultivar em diferentes épocas com proteção, mas a janela regional depende do clima.",
