  "pergunta": "Pimentão: identidade, cores e maturidade",
  "resposta": "Pimentão é fruto de Capsicum annuum L., família Solanaceae. Cultivares doces de fruto grande, sem pungência pronunciada, aparecem verdes, amarelas, vermelhas, laranjas, roxas ou brancas. Em muitos cultivares o verde é estágio menos maduro e a cor final aparece com maturação, mas há cultivares que amadurecem em outras cores. Registrar cultivar e cor/maturidade; cor não é intercambiável para nutrientes. Sinônimos: pimentão, bell pepper, sweet pepper, pimentão verde/vermelho/amarelo.",
