  "alimento": "Pimentão",
  "pergunta": "Pimentão: cultivo e colheita",
  "resposta": "Planta de clima quente, sensível a geada e a extremos de temperatura; calor intenso pode reduzir florescimento e pegamento. Cultivo pode ser a céu aberto ou protegido. Necessita solo bem drenado, fértil e irrigação uniforme; evitar deficiência na floração/frutificação e excesso que favoreça doença radicular. Manejo inclui mudas sadias, tutoramento, rotação de solanáceas, controle de plantas daninhas e monitoramento de pragas/doenças. Colher no estágio exigido pelo mercado: verde firme para colheita imatura ou fruto colorido e maduro, sem rachaduras e com brilho. Mudar o estágio altera cor, açúcar, vitamina C e carotenoides.",
