  "pergunta": "Pimentão: pós-colheita e uso",
  "resposta": "Colher com corte do pedúnculo para não romper ramos, evitar abrasões e resfriar com cuidado. Armazenar refrigerado por período curto, sem temperaturas muito baixas que causem injúria. Fruto cortado deve ser coberto e refrigerado. Pode ser consumido cru, recheado, assado, grelhado, cozido ou em conserva. Congelar em tiras é possível para pratos cozidos, com perda de firmeza.",
