  "categoria": "Fichas técnicas de alimentos",
  "alimento": "Repolho",
  "pergunta": "Repolho: identidade e tipos",
  "resposta": "Repolho de cabeça é Brassica oleracea L. var. capitata, família Brassicaceae. Tipos comuns incluem repolho branco/verde e roxo/vermelho; há cabeças cônicas e arredondadas e cultivares de verão ou inverno. Repolho chinês/napa pertence a outro grupo taxonômico e deve ter ficha independente. Sinônimos: repolho, cabbage, repolho branco, verde, roxo, red cabbage.",
