  "pergunta": "Tomate: identidade, grupos e maturidade",
  "resposta": "Tomate é Solanum lycopersicum L. (sin. Lycopersicon esculentum Mill.), família Solanaceae. Frutos comerciais incluem grupos Santa Cruz, Salada/Beefsteak, Italiano, Cereja e grape, com variações de forma, sólidos solúveis, acidez e cor. Cores maduras incluem vermelho, amarelo, laranja, roxo e verde, conforme cultivar. Estágios de maturação comercial variam entre verde-maduro, pintado, rosado e vermelho. Sinônimos: tomate, tomato, jitomate, tomate de mesa, cereja, italiano, salada.",
