  "resposta": "Planta de clima quente moderado, sensível à geada; calor extremo, chuva e umidade podem prejudicar florescimento, pegamento e sanidade. Produção brasileira ocorre em diversas regiões, em campo aberto e cultivo protegido. Solo fértil, drenado, irrigação uniforme e rotação são importantes. Manejo inclui mudas sadias, tutoramento ou condução conforme hábito, poda quando recomendada para o sistema, polinização, adubação por análise e monitoramento de pragas e doenças. Excesso de água e alternância seca/úmida pode favorecer rachadura e podridão apical. Colher no estágio de cor e firmeza do mercado, com pedúnculo ou sem; para transporte distante, pode-se colher em maturidade fisiológica menos avançada, conforme cadeia de comercialização.",
