  "resposta": "Frutos maduros são sensíveis a impacto e perda de água. Armazenar inteiros, sem empilhar em excesso, e evitar refrigeração muito fria quando verdes ou em amadurecimento, pois pode prejudicar sabor e textura; após amadurecer, refrigerar por curto tempo se necessário. Tomate cortado ou cozido deve ser refrigerado. Usos incluem cru, molho, assado, suco, extrato e conserva. Concentração e adição de sal/óleo diferenciam os produtos processados.",
