  "pergunta": "Tomate: composição nutricional e variação",
  "resposta": "Registro: TBCA BRC0035B, tomate cru, Brasil, Lycopersicon esculentum (sin. Solanum lycopersicum), por 100 g: 17 kcal; 3,82 g de carboidrato total, 2,22 g disponível; 1,04 g de proteína; 0,17 g de lipídios; 1,60 g de fibra; 191 mg de potássio; 15,5 mg de vitamina C; 50,6 µg RAE de vitamina A. Umidade média 94,5 g/100 g a partir de três amostras. TBCA, BRC0035B.\nCultivar, maturidade, cor, tamanho, ambiente e processamento alteram açúcares, ácidos, carotenoides, vitamina C e água. O registro genérico não define cultivar.",
