  "resposta": "ervilha fresca refrigerar e consumir rapidamente ou branquear/congelar; grão seco armazenar seco, ventilado e protegido de insetos. Enlatada exige informação de líquido e sódio. Cozinhar até macia; não comparar grão seco com fresco cozido.",
