  "resposta": "Cicer arietinum L., Fabaceae. Grupos Desi (grãos menores, pigmentados) e Kabuli (maiores, claros) diferem em tegumento, tamanho e adaptação; a produção brasileira costuma comercializar tipos Kabuli, mas origem deve ser confirmada. Sinônimos: grão-de-bico, chickpea, garbanzo, ceci.",
