  "pergunta": "Grão-de-bico: cultivo",
  "resposta": "cultura de estação fresca e relativamente seca, com tolerância limitada ao calor durante florescimento e enchimento. No Brasil é produzida em janelas de inverno seco, especialmente sob irrigação em regiões adequadas; época e cultivar variam. Precisa de solo bem drenado, preferencialmente não salino; semear diretamente, controlar ervas daninhas e doenças, evitar excesso de água e programar irrigação pelo estágio. Colher vagens secas, secar e armazenar grãos com controle de umidade.",
