  "resposta": "seco, armazenar em recipiente limpo e hermético em local fresco e seco; remolho reduz tempo de cozimento, mas tempo depende de idade do lote. Cozinhar até macio. Congelar cozido e drenado ou com caldo. Farinha, homus, conserva e grão cozido são formas distintas.",
