  "resposta": "TBCA lista grão seco cru BRC0016T e cozido/drenado sem óleo e sal BRC0017T. Evitar misturar com preparação temperada, que pode incluir caldo e óleo; códigos devem ser recuperados da ficha oficial. A TACO informa 355 kcal e 21,2 g de proteína por 100 g cru; grão seco cru não representa porção cozida. TACO/TBCA, catálogo de leguminosas.",
