  "pergunta": "Lentilha: cultivo",
  "resposta": "espécie de clima fresco, frequentemente cultivada como cultura de estação seca em regiões produtoras mundiais. Produção brasileira é limitada e mercado inclui importação; não declarar safra nacional ampla sem fonte regional. Exige solo drenado, clima fresco no desenvolvimento e tempo seco na maturação. Semeadura direta, rotação, controle de plantas daninhas e doenças, colheita quando vagens secam e debulha cuidadosa. Manejo de irrigação depende de região e estágio, evitando excesso.",
