  "pergunta": "Lentilha: conservação e preparo",
  "resposta": "grão seco, seco e protegido de insetos. Lentilha pode cozinhar sem remolho; cultivar e idade alteram o tempo. Cozida, refrigerar prontamente ou congelar em porções. A vermelha descascada desmancha mais; a verde/preta tende a manter forma. Produtos enlatados, sopas e preparações temperadas têm registros próprios.",
