  "alimento": "Amaranto",
  "pergunta": "Amaranto: identidade",
  "resposta": "Amaranthus cruentus L. no registro alimentar TBCA; amaranto é o nome de várias espécies do gênero Amaranthus. O grão é um aquênio pequeno, não um cereal botânico de Poaceae, e é chamado pseudocereal pelo uso alimentar. Sinônimos: amaranto, amaranth, grain amaranth, kiwicha.",
