  "resposta": "Secale cereale L., Poaceae. Tipos incluem centeio de inverno e primavera, cultivares para grão, forragem e cobertura; grão integral, farinha e flocos são produtos diferentes. Sinônimos: centeio, rye, grão de centeio.",
