  "categoria": "Fichas técnicas de alimentos",
  "alimento": "Centeio",
  "pergunta": "Centeio: uso, conservação e nutrição",
  "resposta": "guardar seco; moer ou cozinhar conforme produto. Farinha de centeio tem desempenho panificável diferente do trigo. Contém secalinas, proteínas relacionadas ao glúten, e não é indicada para dieta celíaca. Composição depende de integral/refinado, farinha ou grão cozido; usar registro de fonte para a forma exata, não valor de farinha como grão.",
