  "categoria": "Fichas técnicas de alimentos",
  "alimento": "Farro",
  "pergunta": "Farro: nutrição",
  "resposta": "não há perfil único para o nome comercial. Exigir species e milling; comparar somente valores de igual base e preparo. Dados nutricionais sem identidade devem retornar pergunta ou lacuna.",
