  "categoria": "Fichas técnicas de alimentos",
  "alimento": "Quinua",
  "pergunta": "Quinua: pós-colheita e nutrição",
  "resposta": "grão seco, limpo e comercial deve ser lavado/abrasionado conforme instrução para remover saponinas, salvo se já processado. Cozinhar em água; grão cozido, farinha e flocos são distintos. TBCA tem BRC0398A, grão cru importado, Chenopodium quinoa. Catálogo TBCA. Marcar origem importada e espécie; valores crus não equivalem a cozidos.",
