  "pergunta": "Trigo-em-grão: produção no Brasil",
  "resposta": "cultivo de inverno no Sul e sistemas irrigados ou safrinha/sequeiro no Cerrado Central, dependendo de cultivar, município e ZARC. Janela e risco de geada, calor, déficit hídrico e chuva na colheita variam. Embrapa informa trigo safrinha/sequeiro no Cerrado Central com janela indicativa de março a meados de maio em condições e recomendação de 2026; isso é regional, não regra nacional. Embrapa, trigo safrinha no Brasil Central. Manejo inclui cultivar adaptada, semeadura zonada, rotação, nutrição, controle de doenças/plantas daninhas e colheita/seca de grão no ponto.",
