  "resposta": "TBCA BRC0024U descreve semente inteira torrada, sem óleo e sal, dado importado, Cucurbita spp. Por 100 g: 427 kcal; 53,8 g carboidratos totais, 35,4 g disponíveis; 18,6 g proteína; 19,4 g lipídios; 18,4 g fibra. É semente inteira com casca, não pepita descascada; valor é importado e requer cautela de comparabilidade. TBCA, BRC0024U.",
