  "resposta": "“pinha” alimentar costuma ser o fruto de Annona squamosa L., Annonaceae, também chamada ata/fruta-do-conde em certas regiões. A semente negra dentro da polpa não é ingrediente comestível. Pinha é nome regional ambíguo em algumas áreas; confirmar espécie do fruto. A Embrapa identifica A. squamosa como pinha e trata suas sementes em contexto de propagação; sementes também são estudadas por atividade inseticida. Embrapa, sistema produtivo da pinheira, Embrapa, extrato de sementes de pinha.",
