   "https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/1133189/1/Cultivo-da-Bananeira-Irrigada-no-Submedio-Sao-Francisco.pdf",
   "https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/1181069/1/SistemaProducao-Banana-AnaLucia-2025-AINFO.pdf"
